 if($action==='retention'){$run=ny_latest($db);if(!$run)throw new DomainException('sync_required');$id=(string)($b['videoId']??'');if(!isset(ny_videos($db,$run)[$id]))throw new DomainException('unknown_video');$token=ny_token(lab_read(),$run['channel_id']);$r=ny_get($token,'analytics',['ids'=>'channel=='.$run['channel_id'],'startDate'=>gmdate('Y-m-d',time()-30*86400),'endDate'=>gmdate('Y-m-d',time()-86400),'filters'=>'video=='.$id,'dimensions'=>'elapsedVideoTimeRatio','metrics'=>'audienceWatchRatio,relativeRetentionPerformance']);lab_json(200,['report'=>$r]);}
